import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-107: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short107', durationInSeconds: 35.6, fps: 30, width: 1080, height: 1920 };

const B1 = secToFrame(4.0);
const C2 = secToFrame(12.5);
const C3 = secToFrame(17.6);
const C4 = secToFrame(25.0);
const CTA = secToFrame(31.3);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short107: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={B1}>
        <CoverImage src="projects/short-107/cover.png" out={B1 - 10} />
        <HookTitle hold onDark kicker="AI API PRICING" lines={[{ text: 'MINIMAX FLASH' },{ text: 'HALF OF M3', accent: true }]} />
      </FadeOut>
      <FadeOut at={C2}>
        <ToolCard name="M3.1 Flash" tagline="MiniMax, new." chip="15¢" at={B1 + 4}>
          <Panel>
            <Line k="Input / 1M" v="$0.15" good />
            <Line k="Output / 1M" v="$0.60" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={C3}>
        <ToolCard name="M3 Standard" tagline="The regular model." chip="30¢" at={C2 + 4} chipColor={COLORS.danger}>
          <Panel>
            <Line k="Input / 1M" v="$0.30" bad />
            <Line k="Output / 1M" v="$1.20" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={C4}>
        <ToolCard name="Cached input" tagline="Repeat long prompts." chip="1.5¢" at={C3 + 4} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Flash cached" v="$0.015" good />
            <Line k="M3 cached" v="$0.06" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Price only" tagline="Quality not compared." chip="FINE PRINT" at={C4 + 4} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Flash in/out" v="$0.15 / $0.60" good />
            <Line k="M3 in/out" v="$0.30 / $1.20" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-107/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="AI API PRICING" lines={[{ text: 'MINIMAX FLASH' },{ text: 'HALF OF M3', accent: true }]} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Half the bill.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short107;
